insert into public.pages (slug, title, content, meta_title, meta_description, status) values
('impressum', 'Impressum', '<h2>Angaben gemäß § 5 DDG</h2>
<p><strong>Nadeem Abbas</strong><br/>Softwarenavi (private Website, keine Gesellschaft)<br/>Am Forsthaus Gravenbruch 42<br/>63263 Neu-Isenburg<br/>Deutschland</p>
<h3>Kontakt</h3>
<p>Telefon: +49 155 10369734<br/>E-Mail: <a href="mailto:hallo@softwarenavi.de">hallo@softwarenavi.de</a><br/>Kontaktformular: <a href="/kontakt">softwarenavi.de/kontakt</a>. Wir antworten in der Regel innerhalb von zwei Werktagen.</p>
<h3>Verantwortlich für den Inhalt nach § 18 Abs. 2 MStV</h3>
<p>Nadeem Abbas<br/>Am Forsthaus Gravenbruch 42<br/>63263 Neu-Isenburg</p>
<h3>EU-Streitschlichtung</h3>
<p>Die Europäische Kommission stellt eine Plattform zur Online-Streitbeilegung (OS) bereit: <a href="https://ec.europa.eu/consumers/odr/" rel="noopener" target="_blank">https://ec.europa.eu/consumers/odr/</a>. Unsere E-Mail-Adresse finden Sie oben im Impressum.</p>
<h3>Verbraucherstreitbeilegung / Universalschlichtungsstelle</h3>
<p>Wir sind nicht bereit oder verpflichtet, an Streitbeilegungsverfahren vor einer Verbraucherschlichtungsstelle teilzunehmen.</p>
<h2>Haftung für Inhalte</h2>
<p>Als Diensteanbieter sind wir für eigene Inhalte auf diesen Seiten nach den allgemeinen Gesetzen verantwortlich. Wir sind jedoch nicht verpflichtet, übermittelte oder gespeicherte fremde Informationen zu überwachen oder nach Umständen zu forschen, die auf eine rechtswidrige Tätigkeit hinweisen. Verpflichtungen zur Entfernung oder Sperrung der Nutzung von Informationen nach den allgemeinen Gesetzen bleiben hiervon unberührt. Eine diesbezügliche Haftung ist erst ab dem Zeitpunkt der Kenntnis einer konkreten Rechtsverletzung möglich. Bei Bekanntwerden entsprechender Rechtsverletzungen werden wir diese Inhalte umgehend entfernen.</p>
<p>Angaben zu Preisen, Funktionen und Compliance-Merkmalen von Software beruhen auf Herstellerinformationen und eigener Recherche zum jeweils angegebenen Prüfdatum. Sie stellen keine Rechts- oder Steuerberatung dar.</p>
<h2>Haftung für Links</h2>
<p>Unser Angebot enthält Links zu externen Websites Dritter, auf deren Inhalte wir keinen Einfluss haben. Für die Inhalte der verlinkten Seiten ist stets der jeweilige Anbieter oder Betreiber verantwortlich. Die verlinkten Seiten wurden zum Zeitpunkt der Verlinkung auf mögliche Rechtsverstöße überprüft. Bei Bekanntwerden von Rechtsverletzungen werden wir derartige Links umgehend entfernen.</p>
<h2>Urheberrecht</h2>
<p>Die durch die Seitenbetreiber erstellten Inhalte und Werke auf diesen Seiten unterliegen dem deutschen Urheberrecht. Die Vervielfältigung, Bearbeitung, Verbreitung und jede Art der Verwertung außerhalb der Grenzen des Urheberrechtes bedürfen der schriftlichen Zustimmung des jeweiligen Autors bzw. Erstellers. Marken und Logos der vorgestellten Softwareprodukte sind Eigentum der jeweiligen Rechteinhaber.</p>', null, 'Impressum von Softwarenavi: Angaben gemäß § 5 DDG und § 18 Abs. 2 MStV.', 'published'),
('datenschutz', 'Datenschutzerklärung', '<h2>1. Verantwortlicher</h2>
<p>Verantwortlich für die Datenverarbeitung auf dieser Website im Sinne der Datenschutz-Grundverordnung (DSGVO) ist:<br/>Nadeem Abbas, Am Forsthaus Gravenbruch 42, 63263 Neu-Isenburg, Deutschland<br/>Telefon: +49 155 10369734<br/>E-Mail: <a href="mailto:hallo@softwarenavi.de">hallo@softwarenavi.de</a></p>
<h3>Datenschutzbeauftragte/r</h3>
<p>Ein Datenschutzbeauftragter ist nicht benannt, da hierzu keine gesetzliche Pflicht besteht (Art. 37 DSGVO, § 38 BDSG).</p>
<h2>2. Überblick über die Verarbeitungen</h2>
<p>Wir verarbeiten personenbezogene Daten nur, soweit dies zur Bereitstellung einer funktionsfähigen Website sowie unserer Inhalte und Leistungen erforderlich ist oder Sie eingewilligt haben. Im Einzelnen:</p>
<h3>2.1 Bereitstellung der Website und Server-Logfiles</h3>
<p>Beim Aufruf der Website verarbeitet unser Hosting-Dienstleister technisch notwendige Daten (IP-Adresse, Datum und Uhrzeit, aufgerufene Seite, Browsertyp). Rechtsgrundlage ist Art. 6 Abs. 1 lit. f DSGVO; unser berechtigtes Interesse liegt in der sicheren und stabilen Bereitstellung. Logfiles werden nach sieben Tagen gelöscht.</p>
<h3>2.2 Einwilligungsverwaltung (Cookie-Einstellungen)</h3>
<p>Wir speichern Ihre Auswahl im Cookie <code>sl_consent</code> für sechs Monate. Zum Nachweis Ihrer Einwilligung (Art. 7 Abs. 1 DSGVO) protokollieren wir die Auswahl, die Version des Einwilligungstextes, einen zufälligen Identifikator, einen gekürzten, gesalzenen Hash Ihrer IP-Adresse und den Zeitpunkt. Rechtsgrundlage ist Art. 6 Abs. 1 lit. c DSGVO in Verbindung mit § 25 TDDDG. Die Protokolle werden nach drei Jahren gelöscht.</p>
<h3>2.3 Reichweitenmessung</h3>
<p>Nur wenn Sie in die Kategorie „Statistik“ eingewilligt haben, nutzen wir eine selbst gehostete, cookielose Reichweitenmessung mit IP-Anonymisierung. Rechtsgrundlage ist Art. 6 Abs. 1 lit. a DSGVO in Verbindung mit § 25 Abs. 1 TDDDG. Sie können Ihre Einwilligung jederzeit über „Cookie-Einstellungen“ im Fußbereich widerrufen.</p>
<h3>2.4 Bewertungen</h3>
<p>Wenn Sie eine Bewertung abgeben, verarbeiten wir die von Ihnen angegebenen Daten (Anzeigename, optional Position, Unternehmen, Branche, Unternehmensgröße, Land, Nutzungsdauer sowie Ihre Bewertung). Zur Missbrauchsabwehr speichern wir einen gesalzenen Hash Ihrer IP-Adresse. Rechtsgrundlage ist Ihre Einwilligung (Art. 6 Abs. 1 lit. a DSGVO). Bewertungen werden vor der Veröffentlichung geprüft; nicht freigegebene Einreichungen löschen wir nach 90 Tagen. Veröffentlichte Bewertungen bleiben mit dem Anzeigenamen gespeichert, bis Sie deren Löschung verlangen.</p>
<h3>2.5 Newsletter</h3>
<p>Für den Newsletter nutzen wir das Double-Opt-in-Verfahren: Nach der Anmeldung erhalten Sie eine E-Mail, in der Sie die Anmeldung bestätigen. Unbestätigte Anmeldungen löschen wir nach 48 Stunden. Wir speichern Ihre E-Mail-Adresse, den Zeitpunkt der Anmeldung und Bestätigung, einen gesalzenen Hash Ihrer IP-Adresse und die Version des Einwilligungstextes. Rechtsgrundlage ist Art. 6 Abs. 1 lit. a DSGVO sowie § 7 Abs. 2 Nr. 2 UWG. Sie können den Newsletter jederzeit über den Abmeldelink in jeder E-Mail abbestellen. Nach der Abmeldung speichern wir Ihre Adresse in gehashter Form auf einer Sperrliste, um Ihren Widerspruch dauerhaft zu beachten.</p>
<h3>2.6 Kontaktformular und E-Mail</h3>
<p>Anfragen über das Kontaktformular oder per E-Mail verarbeiten wir zur Bearbeitung Ihres Anliegens (Art. 6 Abs. 1 lit. b bzw. f DSGVO). Die Daten werden sechs Monate nach Abschluss der Anfrage gelöscht, sofern keine gesetzlichen Aufbewahrungspflichten entgegenstehen.</p>
<h3>2.7 Partnerlinks</h3>
<p>Klicken Sie auf einen Partnerlink („Zum Anbieter“), erfassen wir den Klick mit Zeitpunkt, Produkt, Referrer, Browserkennung, Länderkennung und einem gesalzenen Hash Ihrer IP-Adresse, um die Provisionsabrechnung nachvollziehen zu können. Eine rohe IP-Adresse speichern wir nicht. Rechtsgrundlage ist Art. 6 Abs. 1 lit. f DSGVO. Die Daten werden nach 14 Monaten gelöscht. Beim anschließenden Besuch der Anbieterseite gelten deren Datenschutzbestimmungen.</p>
<h2>3. Empfänger und Auftragsverarbeiter</h2>
<p>Wir setzen folgende Dienstleister als Auftragsverarbeiter nach Art. 28 DSGVO ein, mit denen jeweils ein Auftragsverarbeitungsvertrag besteht:</p>
<ul>
<li>Datenbank und Speicher: Supabase (Rechenzentrum Frankfurt am Main, EU)</li>
<li>Hosting: Vercel Inc., 440 N Barranca Ave #4133, Covina, CA 91723, USA (Ausführung der Serverfunktionen in der Region Frankfurt am Main; Übermittlung in die USA auf Grundlage des EU-US Data Privacy Framework und von Standardvertragsklauseln)</li>
<li>E-Mail-Versand: Resend (Plus Five Five, Inc., 2261 Market Street #5039, San Francisco, CA 94114, USA; Versand über die EU-Region Irland; Übermittlung in die USA auf Grundlage von Standardvertragsklauseln)</li>
<li>Reichweitenmessung (nur nach Einwilligung): selbst gehostet</li>
</ul>
<h2>4. Übermittlung in Drittländer</h2>
<p>Wir verarbeiten Ihre Daten grundsätzlich in der Europäischen Union. Sollte ein Dienstleister im Einzelfall Daten in einem Drittland verarbeiten, erfolgt dies nur auf Grundlage eines Angemessenheitsbeschlusses (z.&nbsp;B. EU-US Data Privacy Framework) oder geeigneter Garantien wie Standardvertragsklauseln.</p>
<h2>5. Ihre Rechte</h2>
<p>Sie haben das Recht auf:</p>
<ul>
<li>Auskunft über Ihre gespeicherten Daten (Art. 15 DSGVO)</li>
<li>Berichtigung unrichtiger Daten (Art. 16 DSGVO)</li>
<li>Löschung (Art. 17 DSGVO)</li>
<li>Einschränkung der Verarbeitung (Art. 18 DSGVO)</li>
<li>Datenübertragbarkeit (Art. 20 DSGVO)</li>
<li>Widerspruch gegen Verarbeitungen auf Grundlage berechtigter Interessen (Art. 21 DSGVO)</li>
<li>Widerruf erteilter Einwilligungen mit Wirkung für die Zukunft (Art. 7 Abs. 3 DSGVO)</li>
</ul>
<p>Wenden Sie sich dazu an <a href="mailto:hallo@softwarenavi.de">hallo@softwarenavi.de</a>. Wir beantworten Anfragen innerhalb eines Monats.</p>
<h3>Beschwerderecht bei einer Aufsichtsbehörde</h3>
<p>Sie haben das Recht, sich bei einer Datenschutz-Aufsichtsbehörde zu beschweren, insbesondere in dem Mitgliedstaat Ihres Aufenthaltsorts, Ihres Arbeitsplatzes oder des Orts des mutmaßlichen Verstoßes. Zuständig für uns ist der Hessische Beauftragte für Datenschutz und Informationsfreiheit, Gustav-Stresemann-Ring 1, 65189 Wiesbaden, <a href="https://datenschutz.hessen.de" rel="noopener" target="_blank">datenschutz.hessen.de</a>.</p>
<h2>6. Speicherdauer im Überblick</h2>
<ul>
<li>Server-Logfiles: 7 Tage</li>
<li>Unbestätigte Newsletter-Anmeldungen: 48 Stunden</li>
<li>Nicht freigegebene Bewertungen: 90 Tage</li>
<li>Kontaktanfragen: 6 Monate nach Abschluss</li>
<li>Klickdaten zu Partnerlinks: 14 Monate</li>
<li>Einwilligungsnachweise: 3 Jahre</li>
</ul>
<p>Stand: September 2026</p>', null, 'Wie Softwarenavi personenbezogene Daten nach DSGVO verarbeitet, speichert und löscht.', 'published'),
('cookie-richtlinie', 'Cookie-Richtlinie', '<p>Diese Richtlinie erläutert, welche Informationen wir auf Ihrem Endgerät speichern oder auslesen und auf welcher Grundlage dies geschieht. Maßgeblich ist § 25 des Telekommunikation-Digitale-Dienste-Datenschutz-Gesetzes (TDDDG): Das Speichern und Auslesen ist nur mit Ihrer vorherigen Einwilligung zulässig, es sei denn, es ist unbedingt erforderlich, um den von Ihnen gewünschten Dienst bereitzustellen.</p>
<h2>Ihre Auswahl</h2>
<p>Beim ersten Besuch fragen wir Sie, welchen Kategorien Sie zustimmen. Sie können „Alle akzeptieren“, „Nur notwendige“ wählen oder Ihre Auswahl in den Einstellungen anpassen. Ihre Entscheidung können Sie jederzeit über den Link „Cookie-Einstellungen“ im Fußbereich jeder Seite ändern oder widerrufen.</p>
<h2>Kategorien</h2>
<h3>Notwendig (immer aktiv)</h3>
<ul>
<li><strong>sl_consent</strong>: speichert Ihre Einwilligungsentscheidung. Anbieter: Softwarenavi. Speicherdauer: 6 Monate. Rechtsgrundlage: § 25 Abs. 2 Nr. 2 TDDDG.</li>
</ul>
<h3>Statistik (nur mit Einwilligung)</h3>
<ul>
<li><strong>Selbst gehostete Reichweitenmessung</strong>: anonymisierte Messung von Seitenaufrufen ohne Cookies und ohne Weitergabe an Dritte. Anbieter: Softwarenavi (selbst gehostet, EU). Speicherdauer: keine Speicherung auf Ihrem Gerät. Rechtsgrundlage: Art. 6 Abs. 1 lit. a DSGVO, § 25 Abs. 1 TDDDG.</li>
</ul>
<h3>Externe Medien (nur mit Einwilligung)</h3>
<ul>
<li><strong>Eingebettete Videos und Produktdemos</strong>: werden erst nach Ihrer Zustimmung von den jeweiligen Anbietern geladen. Dabei können diese Anbieter Cookies setzen. Speicherdauer: gemäß Anbieter. Rechtsgrundlage: Art. 6 Abs. 1 lit. a DSGVO, § 25 Abs. 1 TDDDG.</li>
</ul>
<h2>Keine Tracking-Cookies von Werbenetzwerken</h2>
<p>Wir setzen keine Cookies von Werbenetzwerken und kein seitenübergreifendes Tracking ein. Partnerlinks werden serverseitig über unsere eigene Weiterleitung erfasst; dabei setzen wir kein Cookie auf Ihrem Gerät.</p>
<h2>Nachweis Ihrer Einwilligung</h2>
<p>Zum Nachweis nach Art. 7 Abs. 1 DSGVO protokollieren wir Ihre Entscheidung serverseitig mit der Version dieser Richtlinie, einem zufälligen Identifikator und einem gesalzenen Hash Ihrer IP-Adresse, nicht mit Ihrer Identität. Einzelheiten finden Sie in der <a href="/datenschutz">Datenschutzerklärung</a>.</p>
<p>Version: 2026-09-v1</p>', null, 'Welche Informationen Softwarenavi auf Ihrem Gerät speichert und auf welcher Grundlage nach § 25 TDDDG.', 'published'),
('agb', 'Allgemeine Geschäftsbedingungen', '<h2>§ 1 Geltungsbereich</h2>
<p>Diese Nutzungsbedingungen gelten für die Nutzung der Website softwarenavi.de (nachfolgend „Softwarenavi“) durch Besucherinnen und Besucher sowie für das Einreichen von Bewertungen.</p>
<h2>§ 2 Leistungen</h2>
<p>Softwarenavi stellt Informationen, Vergleiche und Bewertungen zu Unternehmenssoftware kostenlos zur Verfügung. Ein Anspruch auf eine bestimmte Verfügbarkeit oder Vollständigkeit der Inhalte besteht nicht. Verträge über Software kommen ausschließlich zwischen Ihnen und dem jeweiligen Anbieter zustande.</p>
<h2>§ 3 Keine Rechts- oder Steuerberatung</h2>
<p>Die Inhalte dienen der allgemeinen Information. Angaben zu GoBD-Konformität, E-Rechnung, DATEV-Schnittstellen, Serverstandorten und ähnlichen Merkmalen beruhen auf Herstellerinformationen zum jeweils angegebenen Prüfdatum. Sie ersetzen keine individuelle Beratung durch Steuerberaterinnen, Steuerberater oder Rechtsanwälte.</p>
<h2>§ 4 Bewertungen</h2>
<ul>
<li>Bewertungen müssen auf eigenen Erfahrungen mit der bewerteten Software beruhen.</li>
<li>Unzulässig sind insbesondere Bewertungen durch Anbieter, deren Beschäftigte oder Wettbewerber, bezahlte oder im Austausch gegen Vorteile verfasste Bewertungen sowie beleidigende, unwahre oder rechtswidrige Inhalte.</li>
<li>Wir prüfen Bewertungen vor der Veröffentlichung nach unseren <a href="/redaktionelle-grundsaetze">redaktionellen Grundsätzen</a> und behalten uns vor, Bewertungen abzulehnen oder zu entfernen.</li>
<li>Mit dem Einreichen räumen Sie uns ein einfaches, zeitlich und räumlich unbeschränktes Recht ein, die Bewertung auf Softwarenavi zu veröffentlichen. Sie können die Löschung jederzeit verlangen.</li>
</ul>
<h2>§ 5 Partnerlinks</h2>
<p>Softwarenavi finanziert sich über Partnerlinks. Einzelheiten erläutert der <a href="/affiliate-hinweis">Affiliate-Hinweis</a>.</p>
<h2>§ 6 Haftung</h2>
<p>Wir haften unbeschränkt für Vorsatz und grobe Fahrlässigkeit sowie bei Verletzung von Leben, Körper oder Gesundheit. Im Übrigen ist die Haftung für leicht fahrlässige Pflichtverletzungen auf die Verletzung wesentlicher Pflichten und den vorhersehbaren, typischen Schaden beschränkt.</p>
<h2>§ 7 Schlussbestimmungen</h2>
<p>Es gilt das Recht der Bundesrepublik Deutschland. Sollten einzelne Bestimmungen unwirksam sein, bleibt die Wirksamkeit der übrigen Bestimmungen unberührt.</p>
<p>Stand: September 2026</p>', null, 'Nutzungsbedingungen für softwarenavi.de und das Einreichen von Bewertungen.', 'published'),
('affiliate-hinweis', 'Affiliate-Hinweis und Werbekennzeichnung', '<p><strong>Kurz gesagt:</strong> Softwarenavi ist kostenlos, weil wir über Partnerlinks vergütet werden. Wenn Sie über einen Link mit der Kennzeichnung „Anzeige“ oder „Partnerlink“ zu einem Anbieter wechseln und dort einen Vertrag abschließen, erhalten wir unter Umständen eine Provision. Für Sie ändert sich der Preis dadurch nicht.</p>
<h2>Kennzeichnung</h2>
<p>Gemäß § 5a Abs. 4 UWG kennzeichnen wir kommerzielle Links deutlich. Auf Produktseiten steht der Hinweis „Anzeige“ unmittelbar unter der Schaltfläche „Zum Anbieter“. Alle Partnerlinks tragen das Attribut <code>rel="sponsored"</code> und öffnen sich in einem neuen Tab.</p>
<h2>Partnerprogramme</h2>
<p>Wir nehmen an Partnerprogrammen über Netzwerke wie Awin und Belboon sowie an direkten Programmen einzelner Hersteller teil. Welche Produkte über einen Partnerlink verfügen, ändert sich laufend.</p>
<h2>Unabhängigkeit der Bewertungen</h2>
<ul>
<li>Die Reihenfolge in Listen und Rankings ergibt sich aus der Nutzerbewertung, der Anzahl der Bewertungen oder der von Ihnen gewählten Sortierung. Nicht aus Provisionen.</li>
<li>Anbieter können keine Platzierungen, besseren Bewertungen oder das Entfernen kritischer Bewertungen kaufen.</li>
<li>Produkte ohne Partnerprogramm werden gleichwertig dargestellt und bewertet.</li>
<li>Redaktionelle Fazits in Vergleichen stützen sich auf Bewertungen, Preise und Compliance-Merkmale.</li>
</ul>
<h2>Fragen</h2>
<p>Bei Fragen zu unserem Vergütungsmodell erreichen Sie uns unter <a href="mailto:hallo@softwarenavi.de">hallo@softwarenavi.de</a>.</p>', null, 'Wie sich Softwarenavi finanziert und warum Partnerlinks keinen Einfluss auf Bewertungen haben.', 'published'),
('redaktionelle-grundsaetze', 'Redaktionelle Grundsätze', '<p>Softwarenavi soll Unternehmen in Deutschland helfen, die passende Software zu finden. Das funktioniert nur, wenn Leserinnen und Leser unseren Inhalten vertrauen können. Diese Grundsätze beschreiben, wie wir arbeiten.</p>
<h2>Unabhängigkeit</h2>
<p>Wir finanzieren uns über Partnerlinks (siehe <a href="/affiliate-hinweis">Affiliate-Hinweis</a>). Die Vergütung hat keinen Einfluss auf Bewertungen, Rankings oder redaktionelle Einschätzungen. Anbieter erhalten keinen Einfluss auf Inhalte, bevor sie veröffentlicht werden.</p>
<h2>Wie wir Bewertungen prüfen (§ 5b Abs. 3 UWG)</h2>
<p>Wir veröffentlichen Bewertungen nicht automatisch. Jede eingereichte Bewertung wird vor der Veröffentlichung durch unsere Redaktion geprüft. Dabei kontrollieren wir:</p>
<ul>
<li>ob die Angaben zu Position, Branche und Nutzungsdauer plausibel sind,</li>
<li>ob Hinweise auf eine Bewertung durch den Anbieter, Beschäftigte oder Wettbewerber vorliegen,</li>
<li>ob Mehrfacheinreichungen von derselben Quelle vorliegen (anhand pseudonymisierter technischer Merkmale),</li>
<li>ob die Bewertung beleidigende, unwahre oder rechtswidrige Inhalte enthält.</li>
</ul>
<p>Bewertungen mit dem Hinweis „Verifizierte Nutzung“ haben einen zusätzlichen Nachweis erbracht, etwa ein Profil in einem beruflichen Netzwerk oder einen Nutzungsnachweis. Eine vollständige Gewähr dafür, dass jede Bewertung von einer tatsächlichen Nutzerin oder einem tatsächlichen Nutzer stammt, können wir nicht übernehmen. Freigabe erfolgt in der Regel innerhalb von zwei Werktagen.</p>
<p>Wir veröffentlichen positive wie negative Bewertungen gleichermaßen. Anbieter können auf Bewertungen öffentlich antworten, aber keine Bewertungen entfernen lassen, solange diese unseren Regeln entsprechen.</p>
<h2>Wie Gesamtbewertungen entstehen</h2>
<p>Die Gesamtbewertung eines Produkts ist der Durchschnitt aller veröffentlichten Bewertungen. Die Teilbewertungen „Bedienbarkeit“, „Preis-Leistung“, „Kundenservice“ und „Funktionsumfang“ werden ebenso berechnet. Wir gewichten nicht nach kommerziellen Gesichtspunkten.</p>
<h2>Compliance-Angaben</h2>
<p>Angaben zu GoBD, DATEV-Schnittstelle, E-Rechnung, ELSTER, Serverstandort und AV-Vertrag beruhen auf Herstellerinformationen und eigener Recherche. Wir geben das Datum der letzten Prüfung an. Unbekannte Werte kennzeichnen wir als „keine Angabe“ statt sie zu schätzen.</p>
<h2>Preise</h2>
<p>Alle Preise sind Nettopreise zzgl. Umsatzsteuer, wie im B2B-Bereich üblich. Wir übernehmen die veröffentlichten deutschen Listenpreise der Anbieter und aktualisieren sie regelmäßig. Aktionspreise und individuelle Konditionen können abweichen.</p>
<h2>Korrekturen</h2>
<p>Wenn Ihnen ein Fehler auffällt, schreiben Sie uns an <a href="mailto:hallo@softwarenavi.de">hallo@softwarenavi.de</a>. Wir prüfen jeden Hinweis und korrigieren Fehler transparent.</p>', null, 'Wie Softwarenavi Bewertungen prüft, Rankings bildet und Compliance-Angaben recherchiert.', 'published'),
('barrierefreiheit', 'Erklärung zur Barrierefreiheit', '<p>Softwarenavi ist bemüht, die Website im Einklang mit dem Barrierefreiheitsstärkungsgesetz (BFSG) und der europäischen Norm EN 301 549 barrierefrei zugänglich zu machen. Ziel ist die Konformität mit den Web Content Accessibility Guidelines (WCAG) 2.1 auf Stufe AA.</p>
<h2>Stand der Vereinbarkeit</h2>
<p>Diese Website ist <strong>teilweise konform</strong> mit WCAG 2.1 Stufe AA. Eine vollständige Prüfung durch eine unabhängige Stelle hat noch nicht stattgefunden; die Angaben beruhen auf einer Selbstbewertung.</p>
<h2>Was wir umgesetzt haben</h2>
<ul>
<li>Link „Zum Inhalt springen“ als erstes fokussierbares Element</li>
<li>Semantische Seitenstruktur mit Landmarken und einer logischen Überschriftenhierarchie</li>
<li>Sichtbare Fokusmarkierungen für alle interaktiven Elemente</li>
<li>Bedienbarkeit per Tastatur, Schließen von Overlays mit der Escape-Taste</li>
<li>Deutsche Textalternativen für Symbole und Bewertungssterne</li>
<li>Kontrastverhältnisse von mindestens 4,5:1 für Fließtext in hellem und dunklem Design</li>
<li>Berücksichtigung der Systemeinstellung „Bewegung reduzieren“</li>
<li>Formulare mit beschrifteten Feldern und verständlichen Fehlermeldungen</li>
</ul>
<h2>Bekannte Einschränkungen</h2>
<ul>
<li>Diagramme (z.&nbsp;B. Radar- und Balkendiagramme im Vergleich) sind mit Textzusammenfassungen versehen; eine vollständige tabellarische Alternative fehlt noch auf einzelnen Seiten.</li>
<li>Von Anbietern bereitgestellte Screenshots haben teilweise keine ausführlichen Bildbeschreibungen.</li>
<li>Eingebettete Inhalte Dritter (z.&nbsp;B. Produktvideos) liegen außerhalb unseres Einflusses.</li>
</ul>
<h2>Feedback und Kontakt</h2>
<p>Sind Ihnen Mängel beim barrierefreien Zugang aufgefallen? Schreiben Sie uns an <a href="mailto:hallo@softwarenavi.de">hallo@softwarenavi.de</a> oder nutzen Sie das <a href="/kontakt">Kontaktformular</a>. Wir antworten innerhalb von zwei Wochen.</p>
<h2>Marktüberwachungsbehörde</h2>
<p>Zuständig für die Überwachung der Barrierefreiheitsanforderungen nach dem BFSG ist die Marktüberwachungsstelle der Länder für die Barrierefreiheit von Produkten und Dienstleistungen (MLBF) in Magdeburg.</p>
<p>Diese Erklärung wurde am 15. September 2026 erstellt und zuletzt am 15. September 2026 überprüft.</p>', null, 'Stand der Barrierefreiheit von softwarenavi.de nach BFSG und WCAG 2.1 AA.', 'published')
